/* Original REI landing composition. Existing learning and project routes remain intact. */
window.REIDreamHome=()=>{
 const arrow='<span aria-hidden="true">↗</span>';
 const C=window.REILearningPathCore, saved=window.REILearningStore.readPath();
 const has=Object.values(saved.fields).some(value=>value.trim()), resume=has?saved.last:0;
 const startLabel=has?'Continue my learning':'Start learning';
 const stepDescriptions=['Notice a problem and question your first explanation.','Turn an interest into a feasible research question.','Search deliberately and investigate source credibility.','Compare findings, methods and unanswered questions.','Connect your objective, framework, methods and ethics.','Review your reasoning, seek feedback and plan a revision.'];
 return `<div class="dream-home"><section class="dream-hero" aria-labelledby="dream-title"><div class="dream-hero-meta"><span><i></i> AN INDEPENDENT SPACE FOR CURIOUS MINDS</span><span>RESEARCH, CONNECTED. / 01</span></div><div class="dream-hero-copy"><h1 id="dream-title" aria-label="Curiosity. In a new dimension."><span>Curiosity.</span><span class="dream-outline">In a new</span><span>dimension.</span></h1><div class="dream-intro"><p>Build on the workshop, or begin here on your own. Learn the research process, practice your reasoning and develop a blueprint you can keep improving.</p><a class="button dream-cta" href="#learn/${resume}">${startLabel} ${arrow}</a><a class="dream-text-link" href="#research">Work on my research project <span aria-hidden="true">→</span></a><div class="dream-lens-controls" aria-label="3D magnifying glass controls"><button type="button" data-lens-action="rotate">Rotate ↻</button><button type="button" data-lens-action="inspect" aria-pressed="false">Inspect +</button><button type="button" data-lens-action="reset">Reset</button></div></div></div><div class="dream-art" data-dream-scene aria-hidden="true"><div class="dream-fallback"><i></i><i></i><i></i></div><canvas></canvas><div class="dream-art-coordinate">LENS 001 / CONNECTING IDEAS</div></div><div class="dream-hero-bottom"><button class="dream-scroll" type="button" data-dream-scroll="home-start"><span class="dream-scroll-line" aria-hidden="true"></span>FIND YOUR STARTING POINT</button><span>YOUR IDEAS. YOUR EVIDENCE. YOUR NEXT CHAPTER.</span><span class="dream-live"><i></i> MADE FOR EXPLORATION</span></div></section><section class="home-start" id="home-start" aria-labelledby="home-start-title"><div><h2 id="home-start-title">Where should I start?</h2><p>Choose what you need today. You can move between learning and project work at any time.</p></div><div class="home-start-choices"><article><h3>Build my research skills</h3><p>Start with an observation. Short guides, examples and writing prompts help you build a preliminary research blueprint.</p><a class="button dream-cta" href="#learn/${resume}">${startLabel} ${arrow}</a><p class="home-start-hint">${has?'Your saved learning notes are ready to revisit.':'No topic yet? Step 1 helps you find a starting point.'}</p></article><article><h3>Develop my research project</h3><p>Already have a question or sources? Use the studio to organize papers, connect evidence and develop your proposal.</p><a class="button dream-cta" href="#research">Open research studio ${arrow}</a><p class="home-start-hint">Your projects stay separate from your learning workbook.</p></article></div><div class="home-saved-links"><a href="#workbook">My learning workbook ${arrow}</a><a href="#practice">Practice a research skill ${arrow}</a><a href="#backup">Back up my work ${arrow}</a></div></section><section class="dream-manifesto home-roadmap" id="dream-manifesto" aria-labelledby="home-roadmap-title"><h2 id="home-roadmap-title">From the workshop.<br><span class="dream-silver">Into your own research.</span></h2><p class="home-section-intro">The same sequence, ready to revisit. Each step explains one idea, gives you something to try and adds to your workbook. Independent learners can begin at step 1.</p><ol class="home-step-list">${C.steps.map((step,i)=>`<li><a href="#learn/${i}"><span class="home-step-number">${String(i+1).padStart(2,'0')}</span><div><h3>${step.short}</h3><p>${stepDescriptions[i]}</p></div>${arrow}</a></li>`).join('')}</ol><p class="home-section-note">Your notes form a preliminary blueprint. Review the evidence, methods and ethics with a supervisor before treating it as a research plan.</p><a class="dream-text-link" href="#academy">Need a fuller explanation? Browse the nine detailed lessons ${arrow}</a></section><section class="dream-tools home-practice" aria-labelledby="home-practice-title"><div class="dream-tools-layout"><div><h2 id="home-practice-title">Try it.<br><span class="dream-silver">Explain it. Revise it.</span></h2><p class="home-section-intro">Practice with a fictional example, compare your reasoning with guidance and make a stronger attempt. Then use the same skill in your own research.</p><a class="button dream-cta" href="#practice">Explore all eight activities ${arrow}</a><a class="dream-text-link" href="#learning-evidence">Read the research behind the activities ${arrow}</a></div><div class="dream-tools-links"><a href="#practice/question"><span>01</span><div><h3>Make a question workable.</h3><p>Narrow an overbroad question and explain the boundaries you chose.</p></div>${arrow}</a><a href="#practice/verify"><span>02</span><div><h3>Look beyond a convincing page.</h3><p>Investigate who is behind a claim and trace its original evidence.</p></div>${arrow}</a><a href="#practice/alignment"><span>03</span><div><h3>Match the method to the question.</h3><p>Find a mismatch and explain which evidence could answer the question.</p></div>${arrow}</a></div></div><details class="home-deeper"><summary>More research resources</summary><div><a href="#toolkit">Templates and checklists ${arrow}</a><a href="#seminars">Additional self-guided workshops ${arrow}</a><a href="#notebook">Idea notebook ${arrow}</a><a href="#notebook/draft">Full lesson drafts ${arrow}</a></div><p>Writing in the detailed lessons is kept in Full lesson drafts. Your six-step notes and practice revisions are in My learning workbook.</p></details></section><section class="dream-finale"><h2 data-dream-reveal>Keep your thinking.<br><span class="dream-silver">Keep improving.</span></h2><p>Your learning notes and practice revisions are together in your workbook. Return to an unfinished step, export a readable copy or use it to ask for specific feedback.</p><a href="#workbook" class="button dream-cta">Open my learning workbook ${arrow}</a><p>Your work stays on this device. No account required. <a href="#backup">Keep a backup.</a></p><div class="dream-finale-word" aria-hidden="true">rei</div></section></div>`;
};
